CREATE TABLE IF NOT EXISTS [[+prefix]]aibridge_change_requests (id INT UNSIGNED NOT NULL AUTO_INCREMENT, profile_id INT NOT NULL, operation VARCHAR(64) NOT NULL, resource_id INT NULL, status VARCHAR(32) NOT NULL DEFAULT 'draft', input_json LONGTEXT NOT NULL, before_json LONGTEXT NULL, after_json LONGTEXT NULL, diff_json LONGTEXT NULL, qa_json LONGTEXT NULL, approval_id INT NULL, job_id INT NULL, requested_by VARCHAR(190) NULL, request_id VARCHAR(190) NULL, rejection_reason TEXT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NULL, PRIMARY KEY(id), KEY profile_status(profile_id,status), KEY approval_id(approval_id), KEY job_id(job_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS [[+prefix]]aibridge_approvals (id INT UNSIGNED NOT NULL AUTO_INCREMENT, change_id INT NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'pending', requested_by VARCHAR(190) NULL, requested_at DATETIME NOT NULL, decided_by VARCHAR(190) NULL, decided_at DATETIME NULL, comment TEXT NULL, PRIMARY KEY(id), KEY change_id(change_id), KEY status(status)) ENGINE=InnoDB;
